rows <- lapply(sort(unique(d$case)), function(k) {
    dat <- subset(d,case==k)
    fit <- lm(y ~ 0 + x,data=dat)
    result <- coef_test(fit,vcov='CR2',cluster=dat$cluster,test='Satterthwaite')
    data.frame(case=k,estimate=as.numeric(coef(fit)[1]),se=result$SE[1],df=result$df_Satt[1])
})
write.csv(do.call(rbind,rows),file.path(out,'clubSandwich_reference.csv'),row.names=FALSE)
writeLines(capture.output(sessionInfo()),file.path(out,'R_session_info.txt'))
print(do.call(rbind,rows))
